final class ResidentSecurityService
{
    private int $installationId;
    public function __construct(private ?PDO $pdo=null){$this->pdo??=Connection::pdo();$q=$this->pdo->prepare('SELECT id FROM bh_installations WHERE public_uuid=? LIMIT 1');$q->execute([(string)config('deployment.installation_uuid')]);$this->installationId=(int)$q->fetchColumn();if($this->installationId<1)throw new RuntimeException('Instalación local no encontrada.');}
    public function audit(string $action,?string $entityType=null,?int $entityId=null,array $payload=[],string $result='success',?string $reason=null,?int $propertyId=null,?int $areaId=null,?int $connectorId=null): void
    {try{$u=current_user()??[];$uid=is_numeric($u['id']??null)?(int)$u['id']:null;$pid=is_numeric($u['person_id']??null)?(int)$u['person_id']:null;$stmt=$this->pdo->prepare('INSERT INTO bh_audit_logs (installation_id,actor_local_user_id,actor_person_id,action,entity_type,entity_id,property_id,area_id,connector_instance_id,result,reason,ip_address,user_agent,payload_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$this->installationId,$uid,$pid,$action,$entityType,$entityId,$propertyId,$areaId,$connectorId,$result,$reason,substr((string)($_SERVER['REMOTE_ADDR']??''),0,64),substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500),json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}catch(Throwable $e){ErrorReporter::runtimeLog('visible_audit_failed',['action'=>$action,'message'=>$e->getMessage()]);}}
    public function touchPresence(): void{$u=current_user()??[];$id=is_numeric($u['id']??null)?(int)$u['id']:0;if($id<1)return;$this->pdo->prepare('UPDATE bh_local_users SET last_seen_at=NOW(),last_ip_address=? WHERE id=? AND installation_id=?')->execute([substr((string)($_SERVER['REMOTE_ADDR']??''),0,64),$id,$this->installationId]);}
    public function mailSettings(): array{$q=$this->pdo->prepare('SELECT * FROM bh_mail_settings WHERE installation_id=?');$q->execute([$this->installationId]);$r=$q->fetch()?:[];$secret=EdgeSecretStore::decrypt((string)($r['smtp_secret_encrypted']??''));$r['has_password']=trim((string)($secret['password']??''))!=='';return $r+['transport'=>'smtp','smtp_port'=>587,'smtp_security'=>'tls','enabled'=>0,'has_password'=>false];}
    public function saveMailSettings(array $d): void{$old=$this->mailSettings();$password=(string)($d['smtp_password']??'');if($password===''){$q=$this->pdo->prepare('SELECT smtp_secret_encrypted FROM bh_mail_settings WHERE installation_id=?');$q->execute([$this->installationId]);$enc=(string)($q->fetchColumn()?:'');}else{$enc=EdgeSecretStore::encrypt(['password'=>$password]);}$transport=in_array((string)($d['transport']??''),['smtp','php_mail'],true)?(string)$d['transport']:'smtp';$security=in_array((string)($d['smtp_security']??''),['none','tls','ssl'],true)?(string)$d['smtp_security']:'tls';$this->pdo->prepare('INSERT INTO bh_mail_settings (installation_id,transport,smtp_host,smtp_port,smtp_security,smtp_username,smtp_secret_encrypted,from_email,from_name,enabled) VALUES (?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE transport=VALUES(transport),smtp_host=VALUES(smtp_host),smtp_port=VALUES(smtp_port),smtp_security=VALUES(smtp_security),smtp_username=VALUES(smtp_username),smtp_secret_encrypted=VALUES(smtp_secret_encrypted),from_email=VALUES(from_email),from_name=VALUES(from_name),enabled=VALUES(enabled)')->execute([$this->installationId,$transport,trim((string)($d['smtp_host']??''))?:null,max(1,(int)($d['smtp_port']??587)),$security,trim((string)($d['smtp_username']??''))?:null,$enc,trim((string)($d['from_email']??''))?:null,trim((string)($d['from_name']??''))?:'Property Hub',!empty($d['enabled'])?1:0]);$this->audit('mail.settings.update','mail_settings',$this->installationId,['transport'=>$transport,'enabled'=>!empty($d['enabled'])]);}
    private function mailConfig(): array{$r=$this->mailSettings();$q=$this->pdo->prepare('SELECT smtp_secret_encrypted FROM bh_mail_settings WHERE installation_id=?');$q->execute([$this->installationId]);$sec=EdgeSecretStore::decrypt((string)($q->fetchColumn()?:''));$r['smtp_password']=(string)($sec['password']??'');return $r;}
    public function sendTest(string $to): void{$cfg=$this->mailConfig();SmtpMailer::send($cfg,$to,'Prueba de correo · Property Hub','<h2>Property Hub</h2><p>Este mensaje confirma que el correo saliente de la instalación está funcionando.</p>');$this->audit('mail.test.sent','mail_settings',$this->installationId,['to'=>$to]);}
    public function invitePerson(int $personId): array{$q=$this->pdo->prepare('SELECT p.id,p.display_name,p.email,u.id local_user_id,u.status user_status FROM bh_people p LEFT JOIN bh_local_users u ON u.person_id=p.id AND u.installation_id=p.installation_id WHERE p.id=? AND p.installation_id=? LIMIT 1');$q->execute([$personId,$this->installationId]);$p=$q->fetch();if(!$p)throw new RuntimeException('Persona no encontrada.');$email=trim((string)$p['email']);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('La persona no tiene un correo válido.');$uid=(int)($p['local_user_id']??0);if($uid<1){$this->pdo->prepare("INSERT INTO bh_local_users (installation_id,person_id,email,username,password_hash,user_type,status) VALUES (?,?,?,?,NULL,'resident','pending')")->execute([$this->installationId,$personId,$email,null]);$uid=(int)$this->pdo->lastInsertId();}else{$this->pdo->prepare("UPDATE bh_local_users SET email=?,user_type='resident',status=IF(status IN ('blocked','revoked'),status,'pending') WHERE id=?")->execute([$email,$uid]);}
        $this->pdo->prepare("UPDATE bh_account_invitations SET status='revoked' WHERE installation_id=? AND person_id=? AND status IN ('pending','sent')")->execute([$this->installationId,$personId]);$raw=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$hash=hash('sha256',$raw);$creator=is_numeric(current_user()['id']??null)?(int)current_user()['id']:null;$this->pdo->prepare("INSERT INTO bh_account_invitations (installation_id,person_id,local_user_id,email,token_hash,expires_at,status,created_by_local_user_id) VALUES (?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 48 HOUR),'pending',?)")->execute([$this->installationId,$personId,$uid,$email,$hash,$creator]);$iid=(int)$this->pdo->lastInsertId();$link=self::absoluteUrl('accept-invitation',['token'=>$raw]);$cfg=$this->mailConfig();if(empty($cfg['enabled']))throw new RuntimeException('Configure y habilite primero el correo saliente.');$html='<h2>Bienvenido a Property Hub</h2><p>Hola '.htmlspecialchars((string)$p['display_name'],ENT_QUOTES,'UTF-8').'.</p><p>La administración te invitó a usar Property App. Usa este enlace para establecer tu contraseña:</p><p><a href="'.htmlspecialchars($link,ENT_QUOTES,'UTF-8').'">Activar mi cuenta</a></p><p>El enlace vence en 48 horas y solo puede usarse una vez.</p>';
        try{SmtpMailer::send($cfg,$email,'Invitación a Property Hub',$html);$this->pdo->prepare("UPDATE bh_account_invitations SET status='sent',sent_at=NOW(),last_error=NULL WHERE id=?")->execute([$iid]);$this->audit('resident.account.invitation.sent','person',$personId,['email'=>$email,'invitation_id'=>$iid]);}catch(Throwable $e){$this->pdo->prepare("UPDATE bh_account_invitations SET status='error',last_error=? WHERE id=?")->execute([$e->getMessage(),$iid]);$this->audit('resident.account.invitation.error','person',$personId,['email'=>$email,'invitation_id'=>$iid],'error',$e->getMessage());throw $e;}return ['email'=>$email,'name'=>(string)$p['display_name']];}
    public function invitationByToken(string $raw): ?array{$hash=hash('sha256',trim($raw));$q=$this->pdo->prepare("SELECT ai.*,p.display_name FROM bh_account_invitations ai JOIN bh_people p ON p.id=ai.person_id WHERE ai.token_hash=? AND ai.installation_id=? AND ai.status='sent' AND ai.accepted_at IS NULL AND ai.expires_at>NOW() LIMIT 1");$q->execute([$hash,$this->installationId]);return $q->fetch()?:null;}
    public function acceptInvitation(string $raw,string $password): array{if(strlen($password)<8)throw new InvalidArgumentException('La contraseña debe tener al menos 8 caracteres.');$inv=$this->invitationByToken($raw);if(!$inv)throw new RuntimeException('La invitación no es válida, ya fue usada o venció.');$this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE bh_local_users SET password_hash=?,status='active',email_verified_at=NOW() WHERE id=? AND installation_id=?")->execute([password_hash($password,PASSWORD_DEFAULT),(int)$inv['local_user_id'],$this->installationId]);$this->pdo->prepare("UPDATE bh_account_invitations SET status='accepted',accepted_at=NOW() WHERE id=?")->execute([(int)$inv['id']]);$this->pdo->commit();$this->audit('resident.account.invitation.accepted','person',(int)$inv['person_id'],['email'=>$inv['email'],'invitation_id'=>(int)$inv['id']]);return $inv;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function activity(array $f=[]): array{$where=['a.installation_id=?'];$args=[$this->installationId];$property=(int)($f['property_id']??0);$relation=trim((string)($f['relationship_type']??''));$email=trim((string)($f['email']??''));$userType=trim((string)($f['user_type']??''));$action=trim((string)($f['action']??''));$online=trim((string)($f['online']??''));if($property>0){$where[]='(a.property_id=? OR EXISTS(SELECT 1 FROM bh_property_memberships mx WHERE mx.person_id=a.actor_person_id AND mx.property_id=?))';array_push($args,$property,$property);}if($relation!==''){$where[]='EXISTS(SELECT 1 FROM bh_property_memberships mr WHERE mr.person_id=a.actor_person_id AND mr.relationship_type=? AND mr.status=\'active\')';$args[]=$relation;}if($email!==''){$where[]='u.email LIKE ?';$args[]='%'.$email.'%';}if($userType!==''){$where[]='u.user_type=?';$args[]=$userType;}if($action!==''){$where[]='a.action LIKE ?';$args[]='%'.$action.'%';}if($online==='online')$where[]='u.last_seen_at>=DATE_SUB(NOW(),INTERVAL 2 MINUTE)';if($online==='offline')$where[]='(u.last_seen_at IS NULL OR u.last_seen_at<DATE_SUB(NOW(),INTERVAL 2 MINUTE))';$sql='SELECT a.*,u.email,u.user_type,u.last_seen_at,p.display_name,pr.name property_name,(SELECT GROUP_CONCAT(DISTINCT CONCAT(pm.name,\' · \',m.relationship_type) SEPARATOR \'||\') FROM bh_property_memberships m JOIN bh_properties pm ON pm.id=m.property_id WHERE m.person_id=a.actor_person_id AND m.status=\'active\') memberships FROM bh_audit_logs a LEFT JOIN bh_local_users u ON u.id=a.actor_local_user_id LEFT JOIN bh_people p ON p.id=a.actor_person_id LEFT JOIN bh_properties pr ON pr.id=a.property_id WHERE '.implode(' AND ',$where).' ORDER BY a.created_at DESC,a.id DESC LIMIT 500';$q=$this->pdo->prepare($sql);$q->execute($args);return $q->fetchAll()?:[];}
    public function onlineUsers(?int $propertyId=null): array{$where='u.installation_id=? AND u.user_type=\'resident\'';$args=[$this->installationId];if($propertyId){$where.=' AND EXISTS(SELECT 1 FROM bh_property_memberships m WHERE m.person_id=u.person_id AND m.property_id=? AND m.status=\'active\')';$args[]=$propertyId;}$q=$this->pdo->prepare("SELECT u.id,u.email,u.last_seen_at,u.last_login_at,p.display_name,IF(u.last_seen_at>=DATE_SUB(NOW(),INTERVAL 2 MINUTE),'online','offline') presence,(SELECT GROUP_CONCAT(DISTINCT pr.name ORDER BY pr.name SEPARATOR ' · ') FROM bh_property_memberships m JOIN bh_properties pr ON pr.id=m.property_id WHERE m.person_id=u.person_id AND m.status='active') units FROM bh_local_users u LEFT JOIN bh_people p ON p.id=u.person_id WHERE {$where} ORDER BY presence DESC,p.display_name");$q->execute($args);return $q->fetchAll()?:[];}

    private function token(int $bytes=32): array{$raw=rtrim(strtr(base64_encode(random_bytes($bytes)),'+/','-_'),'=');return[$raw,hash('sha256',$raw)];}
    public function requestPasswordReset(string $email): void{$email=strtolower(trim($email));if(!filter_var($email,FILTER_VALIDATE_EMAIL))return;$q=$this->pdo->prepare("SELECT id,email FROM bh_local_users WHERE installation_id=? AND LOWER(email)=? LIMIT 1");$q->execute([$this->installationId,$email]);$u=$q->fetch();if(!$u)return;[$raw,$hash]=$this->token();$this->pdo->prepare("DELETE FROM bh_password_reset_tokens WHERE installation_id=? AND local_user_id=? AND used_at IS NULL")->execute([$this->installationId,(int)$u['id']]);$this->pdo->prepare("INSERT INTO bh_password_reset_tokens (installation_id,local_user_id,token_hash,expires_at) VALUES (?,?,?,DATE_ADD(NOW(),INTERVAL 60 MINUTE))")->execute([$this->installationId,(int)$u['id'],$hash]);$cfg=$this->mailConfig();if(empty($cfg['enabled']))throw new RuntimeException('El correo saliente no está habilitado.');$link=self::absoluteUrl('reset-password',['token'=>$raw]);SmtpMailer::send($cfg,$email,'Restablecer contraseña · Property Hub','<h2>Restablecer contraseña</h2><p>Recibimos una solicitud para cambiar tu contraseña.</p><p><a href="'.htmlspecialchars($link,ENT_QUOTES,'UTF-8').'">Crear una nueva contraseña</a></p><p>Este enlace vence en 60 minutos. Si no hiciste la solicitud, puedes ignorar este correo.</p>');$this->audit('auth.password_reset.requested','local_user',(int)$u['id'],['email'=>$email]);}
    public function passwordResetByToken(string $raw): ?array{$q=$this->pdo->prepare("SELECT t.*,u.email FROM bh_password_reset_tokens t JOIN bh_local_users u ON u.id=t.local_user_id WHERE t.installation_id=? AND t.token_hash=? AND t.used_at IS NULL AND t.expires_at>NOW() LIMIT 1");$q->execute([$this->installationId,hash('sha256',trim($raw))]);return $q->fetch()?:null;}
    public function resetPassword(string $raw,string $password): void{if(strlen($password)<8)throw new InvalidArgumentException('La contraseña debe tener al menos 8 caracteres.');$t=$this->passwordResetByToken($raw);if(!$t)throw new RuntimeException('El enlace de recuperación no es válido o venció.');$this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE bh_local_users SET password_hash=?,status='active' WHERE id=? AND installation_id=?")->execute([password_hash($password,PASSWORD_DEFAULT),(int)$t['local_user_id'],$this->installationId]);$this->pdo->prepare("UPDATE bh_password_reset_tokens SET used_at=NOW() WHERE id=?")->execute([(int)$t['id']]);$this->pdo->commit();$this->audit('auth.password_reset.completed','local_user',(int)$t['local_user_id'],['email'=>$t['email']]);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function registerResident(string $email,string $password,string $displayName=''): void{$email=strtolower(trim($email));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Indique un correo válido.');if(strlen($password)<8)throw new InvalidArgumentException('La contraseña debe tener al menos 8 caracteres.');$q=$this->pdo->prepare("SELECT p.id,p.display_name FROM bh_people p WHERE p.installation_id=? AND LOWER(p.email)=? AND p.status='active' AND EXISTS(SELECT 1 FROM bh_property_memberships m WHERE m.person_id=p.id AND m.status='active') LIMIT 1");$q->execute([$this->installationId,$email]);$person=$q->fetch();if(!$person)throw new RuntimeException('Ese correo todavía no está autorizado por la administración de esta propiedad.');$q=$this->pdo->prepare("SELECT id,status,email_verified_at FROM bh_local_users WHERE installation_id=? AND (person_id=? OR LOWER(email)=?) LIMIT 1");$q->execute([$this->installationId,(int)$person['id'],$email]);$u=$q->fetch();if($u && !empty($u['email_verified_at']))throw new RuntimeException('Ese correo ya tiene una cuenta. Usa “Olvidé mi contraseña” si no recuerdas la clave.');if($u){$uid=(int)$u['id'];$this->pdo->prepare("UPDATE bh_local_users SET person_id=?,email=?,password_hash=?,user_type='resident',status='pending',email_verified_at=NULL WHERE id=?")->execute([(int)$person['id'],$email,password_hash($password,PASSWORD_DEFAULT),$uid]);}else{$this->pdo->prepare("INSERT INTO bh_local_users (installation_id,person_id,email,password_hash,user_type,status,email_verified_at) VALUES (?,?,?,?, 'resident','pending',NULL)")->execute([$this->installationId,(int)$person['id'],$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$this->pdo->lastInsertId();}$this->sendVerification($uid,$email,(string)($person['display_name']?:$displayName));}
    public function sendVerification(int $uid,string $email,string $name=''): void{$this->pdo->prepare("DELETE FROM bh_email_verification_tokens WHERE installation_id=? AND local_user_id=? AND verified_at IS NULL")->execute([$this->installationId,$uid]);[$raw,$hash]=$this->token();$this->pdo->prepare("INSERT INTO bh_email_verification_tokens (installation_id,local_user_id,token_hash,expires_at) VALUES (?,?,?,DATE_ADD(NOW(),INTERVAL 24 HOUR))")->execute([$this->installationId,$uid,$hash]);$cfg=$this->mailConfig();if(empty($cfg['enabled']))throw new RuntimeException('El correo saliente no está habilitado.');$link=self::absoluteUrl('verify-email',['token'=>$raw]);$hello=$name!==''?'Hola '.htmlspecialchars($name,ENT_QUOTES,'UTF-8').'. ':'';SmtpMailer::send($cfg,$email,'Confirma tu correo · Property Hub','<h2>Confirma tu cuenta</h2><p>'.$hello.'Tu registro está casi listo.</p><p><a href="'.htmlspecialchars($link,ENT_QUOTES,'UTF-8').'">Confirmar mi correo</a></p><p>El enlace vence en 24 horas.</p>');$this->audit('auth.email_verification.sent','local_user',$uid,['email'=>$email]);}
    public function verifyEmail(string $raw): void{$q=$this->pdo->prepare("SELECT * FROM bh_email_verification_tokens WHERE installation_id=? AND token_hash=? AND verified_at IS NULL AND expires_at>NOW() LIMIT 1");$q->execute([$this->installationId,hash('sha256',trim($raw))]);$t=$q->fetch();if(!$t)throw new RuntimeException('El enlace de confirmación no es válido o venció.');$this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE bh_local_users SET email_verified_at=NOW(),status='active' WHERE id=? AND installation_id=?")->execute([(int)$t['local_user_id'],$this->installationId]);$this->pdo->prepare("UPDATE bh_email_verification_tokens SET verified_at=NOW() WHERE id=?")->execute([(int)$t['id']]);$this->pdo->commit();$this->audit('auth.email_verified','local_user',(int)$t['local_user_id']);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}

    public static function absoluteUrl(string $route,array $params=[]): string{$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');$script=(string)($_SERVER['SCRIPT_NAME']??'/public/index.php');return $scheme.'://'.$host.$script.'?'.http_build_query(['route'=>$route]+$params);}
